import sys

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    m = int(input[1])
    answers = input[2:]

    truth_count = [0] * (n + 1)
    for i in range(n):
        sign, ai = answers[i][0], int(answers[i][1:])
        if sign == '+':
            truth_count[ai] += 1
        else:
            truth_count[ai] -= 1

    result = []
    for i in range(1, n + 1):
        if truth_count[i] == m - sum(1 for j in range(n) if answers[j][0] == '+' and int(answers[j][1:]) == i):
            result.append('Truth')
        elif truth_count[i] == m - sum(1 for j in range(n] if answers[j][0] == '-' and int(answers[j][1:]) == i):
            result.append('Lie')
        else:
            result.append('Not defined')

    for r in result:
        print(r)

main()
